```java
// ─── File: src/main/java/com/bank/merge/InterleavingDemo.java ───
package com.bank.merge;

import java.util.logging.ConsoleHandler;
import java.util.logging.Logger;

public class InterleavingDemo {

    private static final Logger log = Logger.getLogger(InterleavingDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
    }

    public static void main(String[] args) {
        log.info("National Bank of India — Stream Merge Auditor (Interleaving String)");
        StreamMergeAuditor auditor = new StreamMergeAuditor();
        log.info("aabcc + dbbca = aadbbcbcac → " +
                auditor.isInterleave("aabcc", "dbbca", "aadbbcbcac"));   // true
        log.info("aabcc + dbbca = aadbbbaccc → " +
                auditor.isInterleave("aabcc", "dbbca", "aadbbbaccc"));   // false
    }
}
```

